const EDIT_LOCK_KEY='b7fi-edit-lock-v1';
const SESSION_ID=sessionStorage.getItem('b7fi-edit-session-id')||('sess_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8));
