exportFullBackup=function(){state.tools=tools;state.config=normalizeConfig(state.config);ensureV0300State();ensureV0305ToolState();const payload={schema:'B7-FI-COMMAND-CENTER-BACKUP',schemaVersion:3,appVersion:'0.31.3',exportedAt:new Date().toISOString(),state};downloadBlob(`B7-FI-Command-Center-Full-Backup-${safeFileStamp()}.json`,JSON.stringify(payload,null,2),'application/json')}

